--- before/src/editor.js
+++ after/src/editor.js
@@ -1,27 +1,40 @@
 import { attachSaveStatus } from "./save-status.js";
+import { createTrailingTask } from "./trailing-task.js";

 export function createDraftEditor({ store, timers, renderDocument, renderStatus }) {
   let current = null;
+  let navigationVersion = 0;
   function close() {
+    const version = ++navigationVersion;
     const leaving = current;
     current = null;
-    if (leaving) leaving.stop();
-    renderDocument(null);
+    if (leaving) {
+      leaving.stop();
+      leaving.save.flush();
+    }
+    if (version === navigationVersion) renderDocument(null);
   }
   return {
     open(id) {
+      const before = navigationVersion;
       close();
-      current = { id, text: store.read(id), visit: {}, stop: attachSaveStatus(store, id, renderStatus) };
+      if (navigationVersion !== before + 1) return;
+      const version = navigationVersion;
+      current = { id, text: store.read(id), visit: {},
+        stop: attachSaveStatus(store, id, renderStatus),
+        save: createTrailingTask(text => store.write(id, text), 120, timers) };
+      if (version !== navigationVersion) return;
       renderDocument({ id, text: current.text });
     },
     edit(text) {
       if (!current) return;
       current.text = text;
-      store.write(current.id, text);
+      current.save.push(text);
     },
     selection() {
       return current && { id: current.id, text: current.text, visit: current.visit };
     },
+    flush() { if (current) current.save.flush(); },
     close,
   };
 }

--- before/src/workspace.js
+++ after/src/workspace.js
@@ -4,15 +4,25 @@
   renderSubmission = () => {}, onSaved = () => {} }) {
   const stop = store.subscribe(event => onSaved(event, navigation));
   const editor = createDraftEditor({ store, timers, renderDocument, renderStatus });
+  let navigationVersion = 0;
   const navigation = {
-    open(id) { renderSubmission(null); editor.open(id); },
+    open(id) {
+      const version = ++navigationVersion;
+      renderSubmission(null);
+      if (version === navigationVersion) editor.open(id);
+    },
     edit(text) { editor.edit(text); },
-    close() { renderSubmission(null); editor.close(); },
+    close() {
+      const version = ++navigationVersion;
+      renderSubmission(null);
+      if (version === navigationVersion) editor.close();
+    },
     submit() {
       const origin = editor.selection();
       if (!origin) return null;
+      editor.flush();
       const receipt = archive.capture({ id: origin.id, text: origin.text });
-      renderSubmission(receipt);
+      if (editor.selection()?.visit === origin.visit) renderSubmission(receipt);
       return receipt;
     },
   };
